-- Create "hooks_rollout_pins" table
CREATE TABLE "hooks_rollout_pins" (
  "id" uuid NOT NULL DEFAULT generate_uuidv7(),
  "seq" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "organization_id" text NULL,
  "version" integer NULL,
  "set_by" text NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT clock_timestamp(),
  "updated_at" timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY ("id"),
  CONSTRAINT "hooks_rollout_pins_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organization_metadata" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "hooks_rollout_pins_set_by_check" CHECK (set_by <> ''::text)
);
-- Create index "hooks_rollout_pins_organization_id_seq_idx" to table: "hooks_rollout_pins"
CREATE INDEX "hooks_rollout_pins_organization_id_seq_idx" ON "hooks_rollout_pins" ("organization_id", "seq" DESC);
-- Create index "hooks_rollout_pins_seq_key" to table: "hooks_rollout_pins"
CREATE UNIQUE INDEX "hooks_rollout_pins_seq_key" ON "hooks_rollout_pins" ("seq");
-- Set comment to column: "id" on table: "hooks_rollout_pins"
COMMENT ON COLUMN "hooks_rollout_pins"."id" IS '@access: confidential';
-- Set comment to column: "seq" on table: "hooks_rollout_pins"
COMMENT ON COLUMN "hooks_rollout_pins"."seq" IS '@access: confidential';
-- Set comment to column: "organization_id" on table: "hooks_rollout_pins"
COMMENT ON COLUMN "hooks_rollout_pins"."organization_id" IS 'NULL for the platform-wide default pin.
@access: confidential';
-- Set comment to column: "version" on table: "hooks_rollout_pins"
COMMENT ON COLUMN "hooks_rollout_pins"."version" IS 'Highest hooks generator version the scope is cleared for. NULL clears an organization override.
@access: confidential';
-- Set comment to column: "set_by" on table: "hooks_rollout_pins"
COMMENT ON COLUMN "hooks_rollout_pins"."set_by" IS 'Email of the staff operator who made the change.
@access: confidential-pii';
-- Set comment to column: "created_at" on table: "hooks_rollout_pins"
COMMENT ON COLUMN "hooks_rollout_pins"."created_at" IS '@access: confidential';
-- Set comment to column: "updated_at" on table: "hooks_rollout_pins"
COMMENT ON COLUMN "hooks_rollout_pins"."updated_at" IS '@access: confidential';
